//   Открой Diffable Data Source → Settings: Wi-Fi.
//   Проверь, что Wi-Fi включён и показан список сетей (список живой: сети появляются и пропадают сами, каждый раз они разные).
//   Выключи переключатель Wi-Fi.
//   Ожидается: переключатель выключен, список доступных сетей исчез.
// Re-run it from the QA tab (Run tests) or in CI; regenerate it from a new passed run.

import XCTest

final class ScenarioVyklyuchenieWiFiTests: XCTestCase {
    override func setUp() {
        continueAfterFailure = false
    }

    func testScenario() {
        let app = QA.launch("com.example.apple-samplecode.modern-collection-viewsDY5L757WXL")

        // Step 2: Open Diffable Data Source as the scenario requires - Cell "Diffable Data Source"
        QA.tap(app.cells["Diffable Data Source"].firstMatch)

        // Step 3: Open Settings: Wi-Fi - Cell "Settings: Wi-Fi"
        QA.tap(app.cells["Settings: Wi-Fi"].firstMatch)
        // Check 1: Wi-Fi включён и показан список сетей
        QA.expectValue(app.switches["Wi-Fi"].firstMatch, "1", "Wi-Fi включён и показан список сетей")
        QA.expect(app.cells.containing(.staticText, identifier: "Wi-Fi").firstMatch, "Wi-Fi включён и показан список сетей")
        QA.expectRows(app.cells, besides: ["Wi-Fi"], "Wi-Fi включён и показан список сетей")

        // Step 4: Выключить переключатель Wi-Fi - Switch "Wi-Fi"
        QA.tap(app.switches["Wi-Fi"].firstMatch)
        // Check 2: Переключатель Wi-Fi выключен
        QA.expectValue(app.switches["Wi-Fi"].firstMatch, "0", "Переключатель Wi-Fi выключен")
        QA.expect(app.cells.containing(.staticText, identifier: "Wi-Fi").firstMatch, "Переключатель Wi-Fi выключен")
        // Check 3: Список доступных сетей исчез
        QA.expect(app.cells.containing(.staticText, identifier: "Wi-Fi").firstMatch, "Список доступных сетей исчез")
        QA.expectValue(app.switches["Wi-Fi"].firstMatch, "0", "Список доступных сетей исчез")
        QA.expectAbsent(app, "breeno-net", "Список доступных сетей исчез")
        QA.expectAbsent(app, "404NotFound", "Список доступных сетей исчез")
        QA.expectAbsent(app, "FBI Surveillance Van", "Список доступных сетей исчез")
        QA.expectAbsent(app, "MarketingDropBox", "Список доступных сетей исчез")
        QA.expectAbsent(app, "Nacho WiFi", "Список доступных сетей исчез")
        QA.expectAbsent(app, "Second Floor", "Список доступных сетей исчез")
        QA.expectAbsent(app, "More Info", "Список доступных сетей исчез")
    }
}
